{"file_path":"src/parser.js","content":"/**
 * The parser for the configuration language described in the task prompt.
 * It turns the document text into a tree of node objects and enforces every
 * structural rule the specification lists, raising a `ParseError` naming the
 * offending line and reason at the first violation.
 *
 * Node shapes:
 *   { type: 'table', explicit, children: { [key]: Node } }
 *   { type: 'array-of-tables', items: [tableNode, ...] }
 *   { type: 'array', items: [Node, ...] }
 *   { type: 'string' | 'integer' | 'float' | 'boolean', value }
 */
import { ParseError } from './errors.js'

const NAME_CHAR = /[A-Za-z0-9_-]/
const INTEGER_RE = /^[+-]?\d+(_\d+)*$/
const FLOAT_RE = /^[+-]?\d+(_\d+)*((\.\d+(_\d+)*[eE][+-]?\d+(_\d+)*)|(\.\d+(_\d+)*)|([eE][+-]?\d+(_\d+)*))$/

function newTable(explicit) {
  return { type: 'table', explicit, children: {} }
}

class LineState {
  constructor(line) {
    this.line = line
    this.pos = 0
  }

  peek() {
    return this.pos < this.line.length ? this.line[this.pos] : undefined
  }

  skipWs() {
    while (this.pos < this.line.length && (this.line[this.pos] === ' ' || this.line[this.pos] === '\t')) {
      this.pos++
    }
  }
}

function fail(lineNum, reason) {
  throw new ParseError(lineNum, reason)
}

function checkLineEnd(state, lineNum, message) {
  state.skipWs()
  const ch = state.peek()
  if (ch === undefined || ch === '#' || ch === ';') return
  fail(lineNum, message)
}

function parseBasicString(state, lineNum) {
  const { line } = state
  state.pos++ // consume opening quote
  let out = ''
  for (;;) {
    if (state.pos >= line.length) fail(lineNum, 'unterminated string')
    const ch = line[state.pos]
    if (ch === '"') {
      state.pos++
      break
    }
    if (ch === '\\') {
      state.pos++
      if (state.pos >= line.length) fail(lineNum, 'unterminated string')
      const esc = line[state.pos]
      switch (esc) {
        case '"':
          out += '"'
          state.pos++
          break
        case '\\':
          out += '\\'
          state.pos++
          break
        case 'n':
          out += '\n'
          state.pos++
          break
        case 't':
          out += '\t'
          state.pos++
          break
        case 'r':
          out += '\r'
          state.pos++
          break
        case '0':
          out += '\0'
          state.pos++
          break
        case 'u': {
          const hex = line.slice(state.pos + 1, state.pos + 5)
          if (hex.length < 4) fail(lineNum, 'unterminated string')
          if (!/^[0-9A-Fa-f]{4}$/.test(hex)) fail(lineNum, 'invalid escape \\u')
          out += String.fromCharCode(parseInt(hex, 16))
          state.pos += 5
          break
        }
        default:
          fail(lineNum, `invalid escape \\${esc}`)
      }
    } else {
      out += ch
      state.pos++
    }
  }
  return { type: 'string', value: out }
}

function parseLiteralString(state, lineNum) {
  const { line } = state
  state.pos++ // consume opening quote
  const start = state.pos
  for (;;) {
    if (state.pos >= line.length) fail(lineNum, 'unterminated string')
    if (line[state.pos] === "'") break
    state.pos++
  }
  const value = line.slice(start, state.pos)
  state.pos++ // consume closing quote
  return { type: 'string', value }
}

function parseName(state, lineNum) {
  const ch = state.peek()
  if (ch === '"') return parseBasicString(state, lineNum).value
  if (ch === "'") return parseLiteralString(state, lineNum).value
  if (ch !== undefined && NAME_CHAR.test(ch)) {
    const start = state.pos
    while (state.pos < state.line.length && NAME_CHAR.test(state.line[state.pos])) state.pos++
    return state.line.slice(start, state.pos)
  }
  fail(lineNum, 'expected a name')
}

function parseDottedName(state, lineNum) {
  const parts = []
  state.skipWs()
  parts.push(parseName(state, lineNum))
  for (;;) {
    state.skipWs()
    if (state.peek() === '.') {
      state.pos++
      state.skipWs()
      parts.push(parseName(state, lineNum))
    } else {
      break
    }
  }
  return parts
}

function parseValue(state, lineNum, path) {
  state.skipWs()
  const ch = state.peek()
  if (ch === undefined || ch === '#' || ch === ';' || ch === ',' || ch === ']' || ch === '}') {
    fail(lineNum, 'expected a value')
  }
  if (ch === '"') return parseBasicString(state, lineNum)
  if (ch === "'") return parseLiteralString(state, lineNum)
  if (ch === '[') return parseArray(state, lineNum, path)
  if (ch === '{') return parseInlineTable(state, lineNum, path)

  const { line } = state
  const start = state.pos
  while (
    state.pos < line.length &&
    line[state.pos] !== ' ' &&
    line[state.pos] !== '\t' &&
    line[state.pos] !== ',' &&
    line[state.pos] !== ']' &&
    line[state.pos] !== '}'
  ) {
    state.pos++
  }
  const text = line.slice(start, state.pos)
  if (text === 'true') return { type: 'boolean', value: true }
  if (text === 'false') return { type: 'boolean', value: false }
  if (INTEGER_RE.test(text)) return { type: 'integer', value: Number(text.replace(/_/g, '')) }
  if (FLOAT_RE.test(text)) return { type: 'float', value: Number(text.replace(/_/g, '')) }
  fail(lineNum, `invalid value ${text}`)
}

function parseArray(state, lineNum, path) {
  state.pos++ // consume '['
  const items = []
  let idx = 0
  for (;;) {
    state.skipWs()
    if (state.peek() === undefined) fail(lineNum, 'unterminated array')
    if (state.peek() === ']') {
      state.pos++
      break
    }
    const value = parseValue(state, lineNum, path.concat(`[${idx}]`))
    items.push(value)
    idx++
    state.skipWs()
    if (state.peek() === undefined) fail(lineNum, 'unterminated array')
    if (state.peek() === ',') {
      state.pos++
      continue
    }
    if (state.peek() === ']') {
      state.pos++
      break
    }
    fail(lineNum, 'trailing text after a value')
  }
  return { type: 'array', items }
}

function parseInlineTable(state, lineNum, path) {
  state.pos++ // consume '{'
  const node = newTable(true)
  state.skipWs()
  if (state.peek() === '}') {
    state.pos++
    return node
  }
  for (;;) {
    state.skipWs()
    const parts = parseDottedName(state, lineNum)
    state.skipWs()
    if (state.peek() !== '=') fail(lineNum, 'expected = in an inline table')
    state.pos++
    state.skipWs()
    const value = parseValue(state, lineNum, path.concat(parts))
    assignValue(node, path, parts, value, lineNum)
    state.skipWs()
    if (state.peek() === undefined) fail(lineNum, 'unterminated inline table')
    if (state.peek() === '}') {
      state.pos++
      break
    }
    if (state.peek() === ',') {
      state.pos++
      continue
    }
    fail(lineNum, 'trailing text after a value')
  }
  return node
}

/** Walks `parts` (all but the last are intermediate) from `container`, creating implicit tables. */
function walkTables(container, parts, path, lineNum) {
  let cur = container
  for (let i = 0; i < parts.length; i++) {
    const key = parts[i]
    path.push(key)
    let node = cur.children[key]
    if (!node) {
      node = newTable(false)
      cur.children[key] = node
    }
    if (node.type === 'table') {
      cur = node
    } else if (node.type === 'array-of-tables') {
      path[path.length - 1] = `${key}[${node.items.length - 1}]`
      cur = node.items[node.items.length - 1]
    } else {
      fail(lineNum, `${path.join('.')} is not a table`)
    }
  }
  return cur
}

function assignValue(container, basePath, parts, valueNode, lineNum) {
  const path = basePath.slice()
  const cur = walkTables(container, parts.slice(0, -1), path, lineNum)
  const leaf = parts[parts.length - 1]
  path.push(leaf)
  if (Object.prototype.hasOwnProperty.call(cur.children, leaf)) {
    fail(lineNum, `key ${path.join('.')} is defined twice`)
  }
  cur.children[leaf] = valueNode
}

function handleHeader(state, lineNum, root) {
  state.pos++ // consume '['
  let isArray = false
  if (state.peek() === '[') {
    isArray = true
    state.pos++
  }
  state.skipWs()
  const parts = parseDottedName(state, lineNum)
  state.skipWs()
  if (state.peek() !== ']') fail(lineNum, 'unterminated table header')
  state.pos++
  if (isArray) {
    if (state.peek() !== ']') fail(lineNum, 'unterminated table header')
    state.pos++
  }
  state.skipWs()
  checkLineEnd(state, lineNum, 'trailing text after a table header')

  const path = []
  const cur = walkTables(root, parts.slice(0, -1), path, lineNum)
  const leaf = parts[parts.length - 1]
  const existing = cur.children[leaf]

  if (!isArray) {
    path.push(leaf)
    if (!existing) {
      const table = newTable(true)
      cur.children[leaf] = table
      return { table, path }
    }
    if (existing.type === 'table') {
      if (existing.explicit) fail(lineNum, `table ${path.join('.')} is defined twice`)
      existing.explicit = true
      return { table: existing, path }
    }
    fail(lineNum, `${path.join('.')} is not a table`)
  } else {
    let arrayNode = existing
    if (!arrayNode) {
      arrayNode = { type: 'array-of-tables', items: [] }
      cur.children[leaf] = arrayNode
    } else if (arrayNode.type !== 'array-of-tables') {
      path.push(leaf)
      fail(lineNum, `${path.join('.')} is not an array of tables`)
    }
    const table = newTable(true)
    arrayNode.items.push(table)
    path.push(`${leaf}[${arrayNode.items.length - 1}]`)
    return { table, path }
  }
}

function handleAssignment(state, lineNum, currentTable, currentPath) {
  const parts = parseDottedName(state, lineNum)
  state.skipWs()
  if (state.peek() !== '=') fail(lineNum, 'expected key = value')
  state.pos++
  state.skipWs()
  const value = parseValue(state, lineNum, currentPath.concat(parts))
  state.skipWs()
  checkLineEnd(state, lineNum, 'trailing text after a value')
  assignValue(currentTable, currentPath, parts, value, lineNum)
}

/** Parses the whole document, returning the root table node. */
export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const root = newTable(true)
  let currentTable = root
  let currentPath = []

  for (let i = 0; i < lines.length; i++) {
    const lineNum = i + 1
    const state = new LineState(lines[i])
    state.skipWs()
    const ch = state.peek()
    if (ch === undefined || ch === '#' || ch === ';') continue
    if (ch === '[') {
      const result = handleHeader(state, lineNum, root)
      currentTable = result.table
      currentPath = result.path
    } else {
      handleAssignment(state, lineNum, currentTable, currentPath)
    }
  }

  return root
}
"}

