 *   { type: 'table', explicit, children: { [key]: Node } }
 *   { type: 'array-of-tables', items: [tableNode, ...] }
 *   { type: 'array', items: [Node, ...] }
 *   { type: 'string' | 'integer' | 'float' | 'boolean', value }
