const INTEGER_RE = /^[+-]?\d+(_\d+)*$/
const FLOAT_RE = /^[+-]?\d+(_\d+)*((\.\d+(_\d+)*[eE][+-]?\d+(_\d+)*)|(\.\d+(_\d+)*)|([eE][+-]?\d+(_\d+)*))$/

function newTable(explicit) {
  return { type: 'table', explicit, children: {} }
