  constructor(line) {
    this.line = line
    this.pos = 0
  }

  peek() {
    return this.pos < this.line.length ? this.line[this.pos] : undefined
  }

  skipWs() {
    while (this.pos < this.line.length && (this.line[this.pos] === ' ' || this.line[this.pos] === '\t')) {
